#!/usr/bin/env node
/**
 * Bundle validator for Claude Code marketplace.
 *
 * Checks that every bundle is *closed*, in both directions:
 *   - each non-by-stack skill that an agent in the bundle loads imperatively
 *     (via the Skill tool, `dex-skill-X:Y`) MUST be listed in the bundle's
 *     includes[] (rule bundle-not-closed).
 *   - each specialist a skill in the bundle delegates to (`dex-X:Y`, X !=
 *     dex-skill-*) MUST also be listed (rule bundle-agent-not-closed).
 *   - each skill or specialist a COMMAND in the bundle names as its executor
 *     (`dex-X:Y`) MUST also be listed (rule bundle-command-not-closed). A
 *     command is the third reference carrier; its body was outside closure
 *     entirely, and the gap was real - /find-bugs (dex-sdlc) names
 *     dex-bug-finder as executor while four bundles shipped the command
 *     without that plugin, so the name silently failed to resolve.
 * Installation is flat - install-bundle.sh installs exactly the includes[]
 * entries, there is no specialist->skill or skill->specialist cascade. So a
 * reference the bundle omits will never be installed, and either the agent
 * silently degrades (graceful-degradation branch) or the delegation has no
 * agent to run.
 *
 * by-stack profile skills (dex-skill-{dotnet,ts,python,...}-*) are exempt
 * ONLY while the bundle ships no skill of that stack: language-agnostic agents
 * load them conditionally per detected project stack (see dex-skill-stack-registry),
 * so they arrive by what the user has installed, not in every bundle. Once a
 * bundle commits to a stack (already includes >=1 skill of it), it is a stack
 * bundle and MUST be closed over that stack too, or its stack-specific agents
 * (e.g. dex-dotnet-coder) silently degrade.
 *
 * Also checks:
 *   - every includes[] entry exists in marketplace.json (else install fails)
 *   - plugin.json version matches marketplace.json for EVERY plugin under
 *     plugins/ (the real two-place sync; bundle.json itself carries no version)
 *   - plugin.json description matches the marketplace.json entry (rule
 *     description-mismatch). Same two-place sync as version, one home:
 *     plugin.json. The catalog copy is generated by npm run sync:marketplace,
 *     never hand-written - 159 of 230 entries had drifted into independently
 *     written texts nobody ever sees.
 *
 * Usage:
 *   node tools/validate-bundle.js <bundle-dir|bundle.json>   # single bundle
 *   node tools/validate-bundle.js all                        # all bundles
 *
 * Exit codes:
 *   0 - clean
 *   1 - at least one error found
 */

import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, relative, resolve, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
// MARKETPLACE_ROOT переносит валидатор на дерево-песочницу: tools/test-rules.js
// прогоняет правило на фикстуре, а не на живом каталоге.
const REPO_ROOT = process.env.MARKETPLACE_ROOT
  ? resolve(process.env.MARKETPLACE_ROOT)
  : resolve(__dirname, '..');
const BUNDLES_DIR = join(REPO_ROOT, 'plugins', 'bundles');
const SPECIALISTS_DIR = join(REPO_ROOT, 'plugins', 'specialists');
const MARKETPLACE_JSON = join(REPO_ROOT, '.claude-plugin', 'marketplace.json');

const COLORS = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  gray: '\x1b[90m',
  bold: '\x1b[1m',
};

const ERROR = 'error';
const WARNING = 'warning';

// --- CLI parsing --------------------------------------------------------

function parseArgs(argv) {
  const positional = argv.slice(2).filter((a) => !a.startsWith('--'));
  return { target: positional[0] || 'all' };
}

// --- Marketplace data ---------------------------------------------------

function loadMarketplacePlugins() {
  if (!existsSync(MARKETPLACE_JSON)) return new Set();
  try {
    const json = JSON.parse(readFileSync(MARKETPLACE_JSON, 'utf8'));
    return new Set((json.plugins || []).map((p) => p.name));
  } catch {
    return new Set();
  }
}

// Map: plugin name -> version as declared in marketplace.json.
function loadMarketplaceVersions() {
  const map = new Map();
  if (!existsSync(MARKETPLACE_JSON)) return map;
  try {
    const json = JSON.parse(readFileSync(MARKETPLACE_JSON, 'utf8'));
    for (const p of json.plugins || []) {
      if (p && p.name && p.version) map.set(p.name, p.version);
    }
  } catch {
    /* ignore */
  }
  return map;
}

// Описание плагина живёт в двух носителях того же типа, что и версия:
// `plugin.json` и запись каталога. Дом описания - `plugin.json`: зондом
// проверено, что при расхождении установленный плагин показывает описание
// манифеста, каталожное не видно нигде после установки (`claude plugin
// details`, 22.08.2026). Копия в каталоге пишется генератором
// `npm run sync:marketplace`, руками - не пишется.
function loadMarketplaceDescriptions() {
  const map = new Map();
  if (!existsSync(MARKETPLACE_JSON)) return map;
  try {
    const json = JSON.parse(readFileSync(MARKETPLACE_JSON, 'utf8'));
    for (const p of json.plugins || []) {
      if (p && p.name && typeof p.description === 'string') map.set(p.name, p.description);
    }
  } catch {
    /* ignore */
  }
  return map;
}

// Категория записи каталога не произвольна: она выводится из того, что в плагине
// лежит, и на дереве совпадает у всех записей. Поле не читает ни один валидатор,
// поэтому пропуск проходил гейт молча (пойман на dex-sdlc-nudge - запись без
// `category` и `keywords`). Ключ - имя записи, значение - `null` при отсутствии
// поля: запись без категории и отсутствие записи вовсе - разные случаи, и второй
// не предмет этого правила.
function loadMarketplaceCategories() {
  const map = new Map();
  if (!existsSync(MARKETPLACE_JSON)) return map;
  try {
    const json = JSON.parse(readFileSync(MARKETPLACE_JSON, 'utf8'));
    for (const p of json.plugins || []) {
      if (p && p.name) map.set(p.name, typeof p.category === 'string' ? p.category : null);
    }
  } catch {
    /* ignore */
  }
  return map;
}

// Порядок веток не произволен: специалист несёт `commands/` наравне с `agents/`,
// а бандл узнаётся только по `bundle.json` - более узкий признак идёт первым.
// Плагин без всех четырёх признаков категории не имеет, и правило на нём молчит.
function categoryFromTree(pluginDir) {
  if (existsSync(join(pluginDir, 'bundle.json'))) return 'bundle';
  if (existsSync(join(pluginDir, 'agents'))) return 'specialist';
  if (existsSync(join(pluginDir, 'skills'))) return 'skill';
  if (existsSync(join(pluginDir, 'hooks')) || existsSync(join(pluginDir, 'commands'))) return 'utility';
  return null;
}

// --- Plugin calls in artifact bodies -------------------------------------

// Вызов, за которым стоит `[справочно]`, называет артефакт как вариант, чужой проекту: реестр зон
// перечисляет все треки, меню стека - все стеки, а едет то, что проекту своё. Условность по задаче
// («для DI - ..., для LINQ - ...») поставку не снимает - какой понадобится, решается в работе.
// Читается только вплотную за вызовом, без переноса строки: пометка в начале следующей строки
// относится к своему тексту, а не к вызову выше, и гасить чужое ребро молча ей нельзя.
const REFERENCE_MARK = /^[ \t]*`\[\u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u043e\]`/;

// Ключ на любое имя каталога, не только на скилл: имя артефакта в теле исполнитель читает как
// «он у меня установлен», поэтому обязательство поставки даёт и `dex-<специалист>:<агент>`.
function pluginCalls(body) {
  const re = /`?(dex-[a-z0-9-]+):[a-z0-9-]+`?/gi;
  const names = [];
  for (const match of body.matchAll(re)) {
    const name = match[1];
    if (/-$/.test(name)) continue; // glob/example artifact: `dex-skill-dotnet-*`
    if (REFERENCE_MARK.test(body.slice(match.index + match[0].length))) continue;
    names.push(name);
  }
  return names;
}

// --- Specialist -> loaded skills map -------------------------------------

// Map: specialist plugin dir name -> Set of catalogue plugins its agent(s) name by the
// `{plugin}:{artifact}` address - skills it loads imperatively and specialists it hands work off to.
// Built once by walking plugins/specialists/**/agents/*.md (same regex as validate-agent.js).
function buildAgentSkillMap(allPluginsInRepo) {
  const map = new Map();

  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      const stat = statSync(full);
      if (stat.isDirectory()) walk(full);
      else if (entry.endsWith('.md') && full.includes('/agents/')) {
        // plugins/specialists/<group>/<plugin>/agents/<agent>.md
        const m = full.match(/plugins\/specialists\/[^/]+\/([^/]+)\/agents\//);
        if (!m) continue;
        const plugin = m[1];
        const body = readFileSync(full, 'utf8');
        const set = map.get(plugin) || new Set();
        for (const skill of pluginCalls(body)) {
          if (!allPluginsInRepo.has(skill) || skill === plugin) continue;
          set.add(skill);
        }
        map.set(plugin, set);
      }
    }
  }
  walk(SPECIALISTS_DIR);
  return map;
}

// Scopes buildSkillAgentMap so an unknown `dex-X:Y` mention isn't mistaken for a real target.
function buildSpecialistPluginsInRepo() {
  const set = new Set();
  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
      } else if (full.endsWith('/.claude-plugin/plugin.json')) {
        try {
          set.add(JSON.parse(readFileSync(full, 'utf8')).name);
        } catch {
          /* ignore */
        }
      }
    }
  }
  walk(SPECIALISTS_DIR);
  return set;
}

// --- Skill -> delegated specialists map ----------------------------------

// Mirror of buildAgentSkillMap: skill plugin name -> Set of specialist plugins
// its body delegates to via `dex-X:Y` (X != dex-skill-*).
function buildSkillAgentMap(allPluginsInRepo) {
  const map = new Map();

  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
      } else if (entry.endsWith('.md') && full.includes('/skills/')) {
        // Тело скилла - это `SKILL.md` и его `references/`: норму, поднятую референсом, исполнитель
        // читает так же, поэтому названный там артефакт обязателен в составе наравне.
        // <plugin>/skills/<name>/[references/]<file>.md -> <plugin>/.claude-plugin/plugin.json
        const rel = full.slice(full.lastIndexOf('/skills/')); // не первое: путь плагина сам бывает plugins/skills/<...>
        const up = rel.split('/').length - 1; // сколько уровней до корня плагина
        let root = full;
        for (let i = 0; i < up; i += 1) root = dirname(root);
        const pj = join(root, '.claude-plugin', 'plugin.json');
        if (!existsSync(pj)) continue;
        let pluginName;
        try {
          pluginName = JSON.parse(readFileSync(pj, 'utf8')).name;
        } catch {
          continue;
        }
        const body = readFileSync(full, 'utf8');
        const set = map.get(pluginName) || new Set();
        for (const agentPlugin of pluginCalls(body)) {
          if (allPluginsInRepo.has(agentPlugin) && agentPlugin !== pluginName) set.add(agentPlugin);
        }
        if (set.size > 0) map.set(pluginName, set);
      }
    }
  }
  walk(join(REPO_ROOT, 'plugins'));
  return map;
}

// --- Command -> referenced skills/specialists map -------------------------

// Третье ребро замыкания. Носителей ссылки на исполнителя три - агент, скилл и
// команда; первые два проверялись, тело команды не проверялось вовсе.
// Разделение по членству в репо, а не по префиксу имени: команда называет и
// `dex-skill-X:Y`, и скилл плагина без префикса (`dex-sdlc:engine`), и агента.
// Форма ссылки та же, что у остальных правил - `plugin:name`; голое имя плагина
// в прозе не ловится (см. docs/VALIDATOR_RULES.md, границы правила).
function buildCommandRefMap(skillPluginsInRepo, specialistPluginsInRepo) {
  const map = new Map();

  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
        continue;
      }
      if (!entry.endsWith('.md') || basename(dirname(full)) !== 'commands') continue;
      // <plugin>/commands/<name>.md -> <plugin>/.claude-plugin/plugin.json
      const pj = join(dirname(dirname(full)), '.claude-plugin', 'plugin.json');
      if (!existsSync(pj)) continue;
      let pluginName;
      try {
        pluginName = JSON.parse(readFileSync(pj, 'utf8')).name;
      } catch {
        continue;
      }
      const body = readFileSync(full, 'utf8');
      const refs = map.get(pluginName) || { skills: new Set(), agents: new Set() };
      for (const target of pluginCalls(body)) {
        if (skillPluginsInRepo.has(target)) refs.skills.add(target);
        else if (specialistPluginsInRepo.has(target)) refs.agents.add(target);
      }
      if (refs.skills.size > 0 || refs.agents.size > 0) map.set(pluginName, refs);
    }
  }
  walk(join(REPO_ROOT, 'plugins'));
  return map;
}

// --- Bundle discovery ---------------------------------------------------

function findAllBundleFiles() {
  const result = [];
  if (!existsSync(BUNDLES_DIR)) return result;
  for (const entry of readdirSync(BUNDLES_DIR)) {
    const bj = join(BUNDLES_DIR, entry, 'bundle.json');
    if (existsSync(bj)) result.push(bj);
  }
  return result;
}

// Состав каждого бандла на диске: правилу `author-only-in-user-bundle` нужен ответ про соседей, а
// не про свой бандл, и при одиночном таргете карта строится так же, как `marketplace.json`.
function buildBundleIncludes() {
  const map = new Map();
  for (const file of findAllBundleFiles()) {
    try {
      const json = JSON.parse(readFileSync(file, 'utf8'));
      map.set(basename(dirname(file)), new Set([...(json.includes || []), ...(json.dependencies || [])]));
    } catch {
      // нечитаемый бандл - забота rule `read-failed` его собственного прогона
    }
  }
  return map;
}

function resolveBundleFile(target) {
  const abs = resolve(target);
  if (existsSync(abs) && statSync(abs).isFile()) return abs;
  // directory or bundle name
  const asDir = join(abs, 'bundle.json');
  if (existsSync(asDir)) return asDir;
  const asName = join(BUNDLES_DIR, basename(target), 'bundle.json');
  if (existsSync(asName)) return asName;
  return null;
}

// --- Validation ---------------------------------------------------------

function validateBundle(bundleFile, marketplacePlugins, marketplaceVersions, agentSkillMap, skillPluginsInRepo, skillAgentMap, commandRefMap, bundleIncludes) {
  const findings = [];
  let bundle;
  try {
    bundle = JSON.parse(readFileSync(bundleFile, 'utf8'));
  } catch (e) {
    return { filepath: bundleFile, findings: [{ level: ERROR, rule: 'read-failed', message: `Failed to parse bundle.json: ${e.message}` }] };
  }

  // Состав бандла разложен на два списка: `includes[]` - то, ради чего бандл собран (профиль роли),
  // `dependencies[]` - то, что подтянуто замыканием от профильного. Установка ставит оба; правила
  // ниже судят состав целиком, поэтому работают с объединением, а не с одним списком.
  const includes = Array.isArray(bundle.includes) ? bundle.includes : [];
  const dependencies = Array.isArray(bundle.dependencies) ? bundle.dependencies : [];
  if (includes.length === 0) {
    findings.push({ level: ERROR, rule: 'empty-includes', message: 'bundle.json has no includes[]' });
    return { filepath: bundleFile, findings };
  }
  const components = [...includes, ...dependencies];
  const includeSet = new Set(components);

  // 0. Один компонент - один список: запись в обоих делает неоднозначным, профильный он или
  //    подтянутый, и разводит счётчики установки.
  const profile = new Set(includes);
  for (const comp of dependencies) {
    if (profile.has(comp)) {
      findings.push({
        level: ERROR,
        rule: 'dependency-also-included',
        message: `"${comp}" is in both includes[] and dependencies[] - a component belongs to exactly one list; drop it from dependencies[] if the bundle ships it for its own sake`,
      });
    }
  }

  // 1. Every include exists in marketplace.json (else install-bundle errors).
  for (const comp of components) {
    if (!marketplacePlugins.has(comp)) {
      findings.push({
        level: ERROR,
        rule: 'include-not-in-marketplace',
        message: `component "${comp}" is not declared in marketplace.json - install-bundle will fail`,
      });
    }
  }

  // 1b. `authorOnly[]` - артефакты автора каталога: их норма живёт в `docs/` каталога, и
  //     валидаторы артефактов снимают с них `catalog-docs-link`, потому что у автора `docs/` лежит
  //     рядом. Оба условия `INV-021` проверяются здесь: артефакт стоит в составе своего бандла и не
  //     едет ни одним бандлом роли. Второе - не формальность: в бандл автора попадают и плагины
  //     замыкания, а такой плагин ставится пользователю, где адрес не разрешится, и молчание
  //     правила становится дырой.
  const authorOnly = Array.isArray(bundle.authorOnly) ? bundle.authorOnly : [];
  const selfBundle = basename(dirname(bundleFile));
  for (const comp of authorOnly) {
    if (!includeSet.has(comp)) {
      findings.push({
        level: ERROR,
        rule: 'author-only-not-included',
        message: `authorOnly[] entry "${comp}" is missing from the author's bundle (includes[]/dependencies[]) - the exemption names a plugin nobody installs from here`,
      });
    }
    const alsoIn = [...bundleIncludes]
      .filter(([name, includes]) => name !== selfBundle && includes.has(comp))
      .map(([name]) => name);
    if (alsoIn.length > 0) {
      findings.push({
        level: ERROR,
        rule: 'author-only-in-user-bundle',
        message: `authorOnly[] entry "${comp}" also ships in ${alsoIn.join(', ')} - a user bundle installs it without the catalogue's docs/, so it is not author-only; drop it from authorOnly[] or from those bundles`,
      });
    }
  }

  // 2. Замыкание: артефакт, названный компонентом бандла, обязан быть в составе.
  //    Условный вызов из этого счёта выведен пометкой `[справочно]` у самого вызова (`pluginCalls`):
  //    отличить его от безусловного по прозе нельзя - «вызови Skill tool ...» стоит и в условной
  //    строке («**Если Redis в стеке** - вызови Skill tool ...»), а по имени нельзя тем более.
  //    Цель ребра судится не по её типу: адрес `{plugin}:{artifact}` в теле агента исполнитель
  //    читает как «он у меня установлен» одинаково для скилла и для соседнего специалиста, которому
  //    агент отдаёт работу дальше по конвейеру («следующий шаг - ...», «handoff потребляют ...»).
  //    Зеркала со стороны скилла (2b) и команды (2c) специалиста уже судят; отбор здесь по одному
  //    лишь skill-типу оставлял класс «агент -> специалист» вне замыкания.
  for (const comp of components) {
    const loaded = agentSkillMap.get(comp);
    if (!loaded) continue; // not a specialist, or names nothing
    for (const target of loaded) {
      if (!includeSet.has(target)) {
        findings.push({
          level: ERROR,
          rule: 'bundle-not-closed',
          message: skillPluginsInRepo.has(target)
            ? `agent "${comp}" loads "${target}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the agent degrades`
            : `agent "${comp}" hands off to "${target}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the handoff has no agent to run`,
        });
      }
    }
  }

  // 2b. Зеркало #2 со стороны скилла: специалист, которому скилл бандла передаёт работу,
  //     обязан быть в составе. Исключение то же.
  for (const comp of components) {
    const delegatesTo = skillAgentMap.get(comp);
    if (!delegatesTo) continue;
    for (const agentPlugin of delegatesTo) {
      if (!includeSet.has(agentPlugin)) {
        findings.push({
          level: ERROR,
          rule: 'bundle-agent-not-closed',
          message: skillPluginsInRepo.has(agentPlugin)
          ? `skill "${comp}" names "${agentPlugin}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the name resolves to nothing`
          : `skill "${comp}" delegates to "${agentPlugin}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the delegation has no agent to run`,
        });
      }
    }
  }

  // 2c. Команда бандла называет исполнителя - скилл или специалиста; он тоже
  //     обязан быть в includes[]. Установка плоская: команда приезжает с своим
  //     плагином и появляется в меню, а названный ею исполнитель - нет, и имя
  //     не резолвится молча. By-stack исключение то же, что в #2 и #2b.
  for (const comp of components) {
    const refs = commandRefMap.get(comp);
    if (!refs) continue;
    for (const skill of refs.skills) {
      if (!includeSet.has(skill)) {
        findings.push({
          level: ERROR,
          rule: 'bundle-command-not-closed',
          message: `command of "${comp}" names skill "${skill}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the command has no skill to call`,
        });
      }
    }
    for (const agentPlugin of refs.agents) {
      if (!includeSet.has(agentPlugin)) {
        findings.push({
          level: ERROR,
          rule: 'bundle-command-not-closed',
          message: `command of "${comp}" names specialist "${agentPlugin}" but the bundle ships it in neither includes[] nor dependencies[] - bundle not closed; add it or the command has no agent to run`,
        });
      }
    }
  }

  // 2d. Обратная сторона трёх проверок замыкания: запись `dependencies[]`, которую в бандле
  //     никто не называет. Списки разводят профиль и подтянутое замыканием, поэтому запись без
  //     тянущего ребра либо профиль, попавший не в тот список, либо хвост удалённого компонента -
  //     оба случая молча раздувают установку.
  const pulled = new Set();
  for (const comp of components) {
    for (const skill of agentSkillMap.get(comp) || []) pulled.add(skill);
    for (const agentPlugin of skillAgentMap.get(comp) || []) pulled.add(agentPlugin);
    const refs = commandRefMap.get(comp);
    if (refs) {
      for (const skill of refs.skills) pulled.add(skill);
      for (const agentPlugin of refs.agents) pulled.add(agentPlugin);
    }
  }
  for (const dep of dependencies) {
    if (pulled.has(dep)) continue;
    findings.push({
      level: ERROR,
      rule: 'dependency-not-pulled',
      message: `"${dep}" stands in dependencies[] but no component of the bundle names it - dependencies[] is what closure pulled, so an entry nothing pulls is either profile composition (move it to includes[]) or the tail of a component already dropped (remove it)`,
    });
  }

  return { filepath: bundleFile, findings };
}

// --- Version sync across ALL plugins -------------------------------------

// Двухместная синхронизация версии касается каждого плагина, не только бандла:
// `plugin.json` <-> запись в `marketplace.json`. Проверка жила внутри
// validateBundle и охватывала лишь bundles/ - рассинхрон обычного плагина
// проходил гейт молча (пойман на dex-sdlc 2.6.1 vs 2.6.0).
function validateVersionSync(marketplaceVersions, marketplaceDescriptions, marketplaceCategories, only) {
  const results = [];
  const walk = (dir) => {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const full = join(dir, entry.name);
      const pluginJson = join(full, '.claude-plugin', 'plugin.json');
      if (existsSync(pluginJson)) {
        if (!only || resolve(full) === resolve(only)) {
          results.push(
            checkVersionSync(pluginJson, marketplaceVersions, marketplaceDescriptions, marketplaceCategories)
          );
        }
        continue;
      }
      walk(full);
    }
  };
  walk(join(REPO_ROOT, 'plugins'));
  return results.filter((r) => r.findings.length > 0);
}

// Сообщение называет признак, по которому категория выведена: иначе автор видит
// вердикт без основания и правит поле наугад.
function categoryEvidence(category) {
  switch (category) {
    case 'bundle':
      return 'bundle.json';
    case 'specialist':
      return 'agents/';
    case 'skill':
      return 'skills/';
    default:
      return 'hooks/ or commands/';
  }
}

function checkVersionSync(pluginJson, marketplaceVersions, marketplaceDescriptions, marketplaceCategories) {
  const findings = [];
  try {
    const pj = JSON.parse(readFileSync(pluginJson, 'utf8'));
    const marketVersion = pj.name ? marketplaceVersions.get(pj.name) : undefined;
    if (pj.version && marketVersion && pj.version !== marketVersion) {
      findings.push({
        level: WARNING,
        rule: 'version-mismatch',
        message: `plugin.json version (${pj.version}) != marketplace.json version (${marketVersion}) for "${pj.name}"`,
      });
    }
    if (typeof pj.description === 'string' && pj.description.trim() && !/[Ѐ-ӿ]/.test(pj.description)) {
      findings.push({
        level: WARNING,
        rule: 'description-not-russian',
        message: `plugin.json description for "${pj.name}" carries no Cyrillic - the /plugin storefront is Russian; write the showcase text in Russian by the artifact body, not by translating the activation field`,
      });
    }
    const marketDescription = pj.name ? marketplaceDescriptions?.get(pj.name) : undefined;
    if (
      typeof pj.description === 'string' &&
      typeof marketDescription === 'string' &&
      pj.description.trim() !== marketDescription.trim()
    ) {
      findings.push({
        level: ERROR,
        rule: 'description-mismatch',
        message: `marketplace.json description != plugin.json description for "${pj.name}" - run \`npm run sync:marketplace\` (plugin.json is the home; the catalog copy is generated)`,
      });
    }
    // Запись без категории и отсутствие записи вовсе - разные случаи: второй ловит
    // include-not-in-marketplace на составе бандла, здесь он предметом не является.
    const hasEntry = Boolean(pj.name) && Boolean(marketplaceCategories?.has(pj.name));
    const expectedCategory = categoryFromTree(dirname(dirname(pluginJson)));
    const declaredCategory = hasEntry ? marketplaceCategories.get(pj.name) : undefined;
    if (hasEntry && expectedCategory && declaredCategory !== expectedCategory) {
      findings.push({
        level: ERROR,
        rule: 'catalog-category-mismatch',
        message: declaredCategory === null
          ? `marketplace.json entry for "${pj.name}" carries no category - the plugin holds ${categoryEvidence(expectedCategory)}, so the entry belongs to "${expectedCategory}"; without it the plugin drops out of its group in the /plugin storefront`
          : `marketplace.json category "${declaredCategory}" != "${expectedCategory}" for "${pj.name}" - the plugin holds ${categoryEvidence(expectedCategory)}`,
      });
    }
  } catch {
    /* plugin.json parse handled by other validators */
  }
  return { filepath: pluginJson, findings };
}

// --- Reporting ----------------------------------------------------------

function formatFinding(f) {
  const isWarning = f.level === WARNING;
  const color = isWarning ? COLORS.yellow : COLORS.red;
  const label = isWarning ? 'WARN ' : 'ERROR';
  return `  ${color}${label}${COLORS.reset} ${COLORS.gray}[${f.rule}]${COLORS.reset} ${f.message}`;
}

function report(results, extraResults = []) {
  let totalErrors = 0;
  let totalWarnings = 0;
  let filesWithIssues = 0;

  for (const result of [...results, ...extraResults]) {
    if (result.findings.length === 0) continue;
    totalErrors += result.findings.filter((f) => f.level !== WARNING).length;
    totalWarnings += result.findings.filter((f) => f.level === WARNING).length;
    filesWithIssues += 1;
    console.log(`\n${COLORS.bold}${relative(REPO_ROOT, result.filepath)}${COLORS.reset}`);
    for (const f of result.findings) console.log(formatFinding(f));
  }

  console.log('');
  console.log(
    `${COLORS.bold}Summary:${COLORS.reset} ${results.length} bundle(s) checked, ` +
      `${COLORS.red}${totalErrors} error(s)${COLORS.reset}, ` +
      `${COLORS.yellow}${totalWarnings} warning(s)${COLORS.reset}` +
      (filesWithIssues > 0 ? `, ${filesWithIssues} file(s) with issues` : '')
  );

  return totalErrors > 0 ? 1 : 0;
}

// --- Main ---------------------------------------------------------------

function buildSkillPluginsInRepo() {
  const set = new Set();
  // Скиллы живут не только в plugins/skills (например plugins/ai-sdlc). Обходим весь
  // plugins/ по SKILL.md - как findAllSkillFiles в validate-skill.js - и берём name из
  // манифеста плагина-владельца. Иначе closure-чек не видит скиллы вне plugins/skills и
  // молча их пропускает (правило bundle-not-closed на них не срабатывает).
  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
      } else if (entry === 'SKILL.md') {
        // <plugin>/skills/<name>/SKILL.md -> <plugin>/.claude-plugin/plugin.json
        const pj = join(dirname(dirname(dirname(full))), '.claude-plugin', 'plugin.json');
        if (existsSync(pj)) {
          try {
            set.add(JSON.parse(readFileSync(pj, 'utf8')).name);
          } catch {
            /* ignore */
          }
        }
      }
    }
  }
  walk(join(REPO_ROOT, 'plugins'));
  return set;
}

// Все плагины репозитория: имя из тела обязывает поставку независимо от типа названного
// артефакта, поэтому цели рёбер сверяются с этим множеством, а не с одним лишь набором скиллов.
function buildAllPluginsInRepo() {
  const set = new Set();
  function walk(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) {
        walk(full);
      } else if (full.endsWith('/.claude-plugin/plugin.json')) {
        try {
          set.add(JSON.parse(readFileSync(full, 'utf8')).name);
        } catch {
          /* ignore */
        }
      }
    }
  }
  walk(join(REPO_ROOT, 'plugins'));
  return set;
}

function main() {
  const { target } = parseArgs(process.argv);
  const marketplacePlugins = loadMarketplacePlugins();
  const marketplaceVersions = loadMarketplaceVersions();
  const marketplaceDescriptions = loadMarketplaceDescriptions();
  const marketplaceCategories = loadMarketplaceCategories();
  const allPluginsInRepo = buildAllPluginsInRepo();
  const agentSkillMap = buildAgentSkillMap(allPluginsInRepo);
  const skillPluginsInRepo = buildSkillPluginsInRepo();
  const specialistPluginsInRepo = buildSpecialistPluginsInRepo();
  const skillAgentMap = buildSkillAgentMap(allPluginsInRepo);
  const commandRefMap = buildCommandRefMap(skillPluginsInRepo, specialistPluginsInRepo);
  const bundleIncludes = buildBundleIncludes();

  let files;
  if (target === 'all') {
    files = findAllBundleFiles();
    if (files.length === 0) {
      console.error(`No bundles found under ${relative(REPO_ROOT, BUNDLES_DIR)}`);
      process.exit(1);
    }
  } else {
    const f = resolveBundleFile(target);
    if (!f) {
      console.error(`Bundle not found: ${target}`);
      process.exit(1);
    }
    files = [f];
  }

  const results = files.map((f) =>
    validateBundle(f, marketplacePlugins, marketplaceVersions, agentSkillMap, skillPluginsInRepo, skillAgentMap, commandRefMap, bundleIncludes)
  );
  // Одиночный таргет сверяет версию только своего плагина, `all` - всех.
  const versionResults =
    target === 'all'
      ? validateVersionSync(marketplaceVersions, marketplaceDescriptions, marketplaceCategories)
      : validateVersionSync(
          marketplaceVersions,
          marketplaceDescriptions,
          marketplaceCategories,
          dirname(files[0])
        );
  process.exit(report(results, versionResults));
}

main();
